import { useEffect, useState } from "react";
import "./App.css";

function App() {
  const [sec, setSec] = useState(0);

  useEffect(() => {
    const interval = setInterval(
      setSec((prevState) => prevState + 1),
      1000
    );

    return () => clearInterval(interval);
  }, []);

  return <div></div>;
}

export default App;
